<?php
declare(strict_types=1);
require_once __DIR__.'/../life/bootstrap.php';
/** Account-bound OAuth grants. No plaintext access/refresh tokens are persisted. */
final class LifeConnections {
 public const ORIGIN='https://life.ayodsgn.com';
 public const RESOURCE=self::ORIGIN.'/api/planner/mcp/';
 public const SCOPES=['life.read','life.write','offline_access'];
 public function __construct(public PDO $db){foreach([
 'CREATE TABLE IF NOT EXISTS life_oauth_client (id VARCHAR(64) PRIMARY KEY, name VARCHAR(100) NOT NULL, redirects LONGTEXT NOT NULL, created_at BIGINT NOT NULL)',
 'CREATE TABLE IF NOT EXISTS life_oauth_pending (id CHAR(32) PRIMARY KEY, request_json LONGTEXT NOT NULL, expires_at BIGINT NOT NULL, used INT NOT NULL)',
 'CREATE TABLE IF NOT EXISTS life_oauth_grant (id CHAR(32) PRIMARY KEY, account_id INT NOT NULL, client_id VARCHAR(64) NOT NULL, scopes VARCHAR(200) NOT NULL, credential CHAR(64) NOT NULL, created_at BIGINT NOT NULL, revoked INT NOT NULL)',
 'CREATE TABLE IF NOT EXISTS life_oauth_token (token_hash CHAR(64) PRIMARY KEY, kind VARCHAR(16) NOT NULL, grant_id CHAR(32) NOT NULL, payload LONGTEXT NOT NULL, expires_at BIGINT NOT NULL, used INT NOT NULL)',
 'CREATE TABLE IF NOT EXISTS life_oauth_event (id CHAR(32) PRIMARY KEY, account_id INT NOT NULL, grant_id CHAR(32) NOT NULL, operation VARCHAR(100) NOT NULL, record_id VARCHAR(64) NOT NULL, at BIGINT NOT NULL)',
 'CREATE TABLE IF NOT EXISTS life_oauth_receipt (grant_id CHAR(32) NOT NULL, request_id VARCHAR(100) NOT NULL, fingerprint CHAR(64) NOT NULL, result_json LONGTEXT NOT NULL, PRIMARY KEY(grant_id,request_id))',
 'CREATE TABLE IF NOT EXISTS life_oauth_rate (bucket CHAR(64) PRIMARY KEY, attempts INT NOT NULL, reset_at BIGINT NOT NULL)'
 ]as$sql)$db->exec($sql);}
 public function limit(string $key,int $max=120):void{$key=hash('sha256',$key);$this->db->prepare('DELETE FROM life_oauth_rate WHERE reset_at<?')->execute([time()]);$sql=$this->db->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite'?'INSERT OR IGNORE':'INSERT IGNORE';$this->db->prepare($sql.' INTO life_oauth_rate VALUES (?,0,?)')->execute([$key,time()+3600]);$this->db->prepare('UPDATE life_oauth_rate SET attempts=attempts+1 WHERE bucket=?')->execute([$key]);$q=$this->db->prepare('SELECT attempts FROM life_oauth_rate WHERE bucket=?');$q->execute([$key]);if((int)$q->fetchColumn()>$max)throw new LifeError('Too many connection requests. Try again later.',429);}
 public static function scopes(mixed $value):array{if(!is_string($value))throw new LifeError('Invalid OAuth scope.',400);$s=array_values(array_unique(array_filter(explode(' ',$value))));if(!$s||array_diff($s,self::SCOPES)||!in_array('life.read',$s,true))throw new LifeError('Request life.read and optional life.write / offline_access.',400);return$s;}
 public static function redirect(mixed $url):string{$url=LifeStore::text($url,2048,true);$p=parse_url($url);if(!$p||($p['scheme']??'')!=='https'||empty($p['host'])||isset($p['user'])||isset($p['pass'])||isset($p['fragment'])||preg_match('/[\x00-\x20\x7f]/',$url))throw new LifeError('Use an exact HTTPS callback URL.',400);parse_str($p['query']??'',$q);if(isset($q['code'])||isset($q['state'])||isset($q['error']))throw new LifeError('Callback URL contains reserved parameters.',400);return$url;}
 public function register(array $in):array{$redirects=$in['redirect_uris']??null;if(!is_array($redirects)||!array_is_list($redirects)||!$redirects||count($redirects)>10)throw new LifeError('Provide up to ten exact callback URLs.',400);$redirects=array_map([self::class,'redirect'],$redirects);if(($in['token_endpoint_auth_method']??'none')!=='none')throw new LifeError('Use a public client with PKCE and token_endpoint_auth_method none.',400);$id=bin2hex(random_bytes(24));$name=LifeStore::text($in['client_name']??'AI assistant',100,true);$this->db->prepare('INSERT INTO life_oauth_client VALUES (?,?,?,?)')->execute([$id,$name,json_encode($redirects,JSON_THROW_ON_ERROR),time()]);return['client_id'=>$id,'client_id_issued_at'=>time(),'client_name'=>$name,'redirect_uris'=>$redirects,'token_endpoint_auth_method'=>'none','grant_types'=>['authorization_code','refresh_token'],'response_types'=>['code']];}
 public function client(string $id):array{$q=$this->db->prepare('SELECT * FROM life_oauth_client WHERE id=?');$q->execute([$id]);$c=$q->fetch(PDO::FETCH_ASSOC);if(!$c)throw new LifeError('Unknown OAuth client.',400);return$c;}
 public function pending(array $in):string{$c=$this->client(LifeStore::text($in['client_id']??'',64,true));$redirect=self::redirect($in['redirect_uri']??'');if(!in_array($redirect,json_decode($c['redirects'],true),true))throw new LifeError('Callback URL is not registered.',400);if(($in['response_type']??'')!=='code'||($in['code_challenge_method']??'')!=='S256'||!is_string($in['code_challenge']??null)||!preg_match('/^[A-Za-z0-9_-]{43}$/D',$in['code_challenge']))throw new LifeError('Authorization code with S256 PKCE is required.',400);if(($in['resource']??self::RESOURCE)!==self::RESOURCE)throw new LifeError('Incorrect planner resource.',400);$in=['client_id'=>$c['id'],'redirect_uri'=>$redirect,'state'=>LifeStore::text($in['state']??'',1024),'scope'=>implode(' ',self::scopes($in['scope']??'life.read')),'challenge'=>$in['code_challenge'],'resource'=>self::RESOURCE];$id=LifeStore::id();$this->db->prepare('INSERT INTO life_oauth_pending VALUES (?,?,?,0)')->execute([$id,json_encode($in,JSON_THROW_ON_ERROR),time()+600]);return$id;}
 public function pendingInfo(string $id):array{$q=$this->db->prepare('SELECT * FROM life_oauth_pending WHERE id=? AND used=0 AND expires_at>?');$q->execute([$id,time()]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new LifeError('This connection request expired. Start again in your assistant.',410);$p=json_decode($r['request_json'],true);return$p+['client_name'=>$this->client($p['client_id'])['name']];}
 private function credential(int $account):string{$q=$this->db->prepare('SELECT email,google_sub FROM life_account WHERE id=?');$q->execute([$account]);$a=$q->fetch(PDO::FETCH_ASSOC);if(!$a)throw new LifeError('Account unavailable.',401);$q=$this->db->prepare('SELECT password_hash FROM life_email_auth WHERE account_id=?');$q->execute([$account]);$emailHash=$q->fetchColumn()?:'';$owner='';if($account===1){$q=$this->db->query('SELECT password_hash FROM life_owner WHERE id=1');$owner=$q->fetchColumn()?:'';}return hash('sha256',json_encode([$a,$emailHash,$owner],JSON_THROW_ON_ERROR));}
 public function decide(int $account,string $pending,bool $allow,bool $write):array{$p=$this->pendingInfo($pending);$url=$p['redirect_uri'];$params=['state'=>$p['state'],'iss'=>self::ORIGIN];$this->db->beginTransaction();try{$q=$this->db->prepare('UPDATE life_oauth_pending SET used=1 WHERE id=? AND used=0 AND expires_at>?');$q->execute([$pending,time()]);if($q->rowCount()!==1)throw new LifeError('Connection request was already used.',409);if(!$allow)$params['error']='access_denied';else{$scopes=self::scopes($p['scope']);if(!$write)$scopes=array_values(array_diff($scopes,['life.write']));$id=LifeStore::id();$credential=$this->credential($account);$this->db->prepare('INSERT INTO life_oauth_grant VALUES (?,?,?,?,?,?,0)')->execute([$id,$account,$p['client_id'],implode(' ',$scopes),$credential,time()]);$params['code']=$this->issue('code',$id,['client_id'=>$p['client_id'],'redirect_uri'=>$url,'challenge'=>$p['challenge'],'resource'=>self::RESOURCE],300);$this->event($account,$id,'connection.authorized','');}$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}return['redirect'=>$url.(str_contains($url,'?')?'&':'?').http_build_query($params,'','&',PHP_QUERY_RFC3986)];}
 private function issue(string $kind,string $grant,array $payload,int $seconds):string{$t=bin2hex(random_bytes(32));$this->db->prepare('INSERT INTO life_oauth_token VALUES (?,?,?,?,?,0)')->execute([hash('sha256',$t),$kind,$grant,json_encode($payload,JSON_THROW_ON_ERROR),time()+$seconds]);return$t;}
 private function grant(string $id):array{$q=$this->db->prepare('SELECT * FROM life_oauth_grant WHERE id=? AND revoked=0');$q->execute([$id]);$g=$q->fetch(PDO::FETCH_ASSOC);if(!$g||!hash_equals($g['credential'],$this->credential((int)$g['account_id'])))throw new LifeError('Connection is revoked or no longer valid.',401);return$g;}
 public function exchange(array $in):array{$kind=match($in['grant_type']??''){'authorization_code'=>'code','refresh_token'=>'refresh',default=>throw new LifeError('Unsupported grant type.',400)};$raw=$in[$kind==='code'?'code':'refresh_token']??'';if(!is_string($raw)||!preg_match('/^[a-f0-9]{64}$/D',$raw))throw new LifeError('Invalid grant.',400);$q=$this->db->prepare('SELECT * FROM life_oauth_token WHERE token_hash=? AND kind=?');$hash=hash('sha256',$raw);$q->execute([$hash,$kind]);$t=$q->fetch(PDO::FETCH_ASSOC);if(!$t||$t['expires_at']<=time())throw new LifeError('Invalid or expired grant.',400);$p=json_decode($t['payload'],true);$g=$this->grant($t['grant_id']);if(($in['client_id']??'')!==$g['client_id']||($in['resource']??self::RESOURCE)!==self::RESOURCE)throw new LifeError('Grant does not belong to this client or resource.',400);if($kind==='code'){$v=$in['code_verifier']??'';if(($in['redirect_uri']??'')!==$p['redirect_uri']||!is_string($v)||!preg_match('/^[A-Za-z0-9._~-]{43,128}$/D',$v)||!hash_equals($p['challenge'],rtrim(strtr(base64_encode(hash('sha256',$v,true)),'+/','-_'),'=')))throw new LifeError('PKCE verification failed.',400);}if($t['used']){$this->revoke((int)$g['account_id'],$g['id']);throw new LifeError('Grant already used.',400);}$replay=false;$this->db->beginTransaction();try{$q=$this->db->prepare('UPDATE life_oauth_token SET used=1 WHERE token_hash=? AND used=0');$q->execute([$hash]);if($q->rowCount()!==1){$replay=true;throw new LifeError('Grant already used.',400);}$out=['access_token'=>$this->issue('access',$g['id'],['resource'=>self::RESOURCE],3600),'token_type'=>'Bearer','expires_in'=>3600,'scope'=>$g['scopes']];if(in_array('offline_access',explode(' ',$g['scopes']),true))$out['refresh_token']=$this->issue('refresh',$g['id'],['resource'=>self::RESOURCE],30*86400);$this->db->commit();return$out;}catch(Throwable$e){if($this->db->inTransaction())$this->db->rollBack();if($replay)$this->revoke((int)$g['account_id'],$g['id']);throw$e;}}
 public function authenticate(string $authorization):array{if(!preg_match('/^Bearer ([a-f0-9]{64})$/D',$authorization,$m))throw new LifeError('Connect your planner account first.',401);$q=$this->db->prepare('SELECT * FROM life_oauth_token WHERE token_hash=? AND kind=? AND used=0 AND expires_at>?');$q->execute([hash('sha256',$m[1]),'access',time()]);$t=$q->fetch(PDO::FETCH_ASSOC);if(!$t)throw new LifeError('Your planner connection expired. Reconnect it.',401);$g=$this->grant($t['grant_id']);$this->limit('grant:'.$g['id'],1200);return$g;}
 public function list(int $account):array{$q=$this->db->prepare('SELECT g.id,c.name,g.scopes,g.created_at,g.revoked FROM life_oauth_grant g JOIN life_oauth_client c ON c.id=g.client_id WHERE account_id=? ORDER BY g.created_at DESC');$q->execute([$account]);return$q->fetchAll(PDO::FETCH_ASSOC);}
 public function revoke(int $account,string $id):void{$this->db->prepare('UPDATE life_oauth_grant SET revoked=1 WHERE id=? AND account_id=?')->execute([$id,$account]);}
 public function revokeToken(array $in):void{$q=$this->db->prepare('SELECT grant_id FROM life_oauth_token WHERE token_hash=?');$q->execute([hash('sha256',is_string($in['token']??null)?$in['token']:'')]);$id=$q->fetchColumn();if(!$id)return;try{$g=$this->grant($id);if(($in['client_id']??'')===$g['client_id'])$this->revoke((int)$g['account_id'],$id);}catch(LifeError){}}
 public function event(int $account,string $grant,string $op,string $record):void{$this->db->prepare('INSERT INTO life_oauth_event VALUES (?,?,?,?,?,?)')->execute([LifeStore::id(),$account,$grant,$op,$record,time()]);}
 public function events(int $account):array{$q=$this->db->prepare('SELECT e.operation,e.record_id,e.at,c.name FROM life_oauth_event e JOIN life_oauth_grant g ON g.id=e.grant_id JOIN life_oauth_client c ON c.id=g.client_id WHERE e.account_id=? ORDER BY e.at DESC LIMIT 100');$q->execute([$account]);return$q->fetchAll(PDO::FETCH_ASSOC);}
}
